// ---------- Errors, headers, limits ----------

export type ErrorCode = "invalid_json" | "invalid_key" | "insufficient_credits" | "daily_limit_reached" | "account_suspended" | "not_found" | "invalid_request" | "tier_unavailable" | "rate_limited" | "internal_error" | "service_unavailable" | "timeout"

/** Error codes with HTTP status and meaning, as in the contract. */
export const ERROR_CODES = [
  {
    "status": 400,
    "code": "invalid_json",
    "message": "The request body is not valid JSON."
  },
  {
    "status": 401,
    "code": "invalid_key",
    "message": "The key is missing, unknown or blocked."
  },
  {
    "status": 402,
    "code": "insufficient_credits",
    "message": "Not enough credits for this call."
  },
  {
    "status": 402,
    "code": "daily_limit_reached",
    "message": "The daily spending limit of your account has been reached."
  },
  {
    "status": 403,
    "code": "account_suspended",
    "message": "Your account is suspended, for example because of a payment dispute. Contact us; credits and receipts stay readable in the console."
  },
  {
    "status": 404,
    "code": "not_found",
    "message": "What you asked for does not exist, for example no product for this barcode or no entry with this id in your catalog."
  },
  {
    "status": 422,
    "code": "invalid_request",
    "message": "The JSON is valid, but a field is missing, has a wrong value or exceeds a limit. The message names the fields."
  },
  {
    "status": 422,
    "code": "tier_unavailable",
    "message": "The chosen tier is not available yet or not yet enabled for live keys. AI endpoints only."
  },
  {
    "status": 429,
    "code": "rate_limited",
    "message": "Too many calls with this key in a short time."
  },
  {
    "status": 500,
    "code": "internal_error",
    "message": "An error on our side. Nothing is deducted."
  },
  {
    "status": 503,
    "code": "service_unavailable",
    "message": "The endpoint is temporarily blocked or not enabled yet, or a service the response depends on returns nothing usable (model provider, USDA FoodData Central, Open Food Facts): it does not answer, throttles, reports an error or returns only invalid answers. That includes an estimate in which the model names no portion. Nothing is deducted."
  },
  {
    "status": 504,
    "code": "timeout",
    "message": "The time limit ran out before a usable estimate was ready. AI endpoints only, and only in this case; every other failure of the model is 503. Nothing is deducted."
  }
] as const

